**Gates before launch.** I launch only if four gates pass, and I stop at the first failure. First, I confirm that spe/predictions/r04.yaml and spe/plans/r04.md are committed, and that spe/evals/tasks/answers.json holds 50 tickets. The eval set has been 40 tickets until now. If it still holds 40, I stop and ask you, because the plan says 50 and that conflict is your call. Second, the grader selftest: grade.py must pass the oracle answers 50 of 50 and fail an empty file and a wrong file. Third, the control: I regrade round 3's saved labels with this grade.py. Any change from the round 3 numbers in prediction-log.md is a grader change, and I log it before any trial runs. Fourth, a dry run with `only: ['B:T001','C2:T001','C2:T017']` and `dryTrials: 2`. Every run must return valid output with a clean peek scan, a grade, and a judge score. The dry run also measures cost per trial. My unmeasured estimate is about $38 against the $40 cap ($25 for 500 trials, $6 for runner agents, $7.50 for 50 Opus judge calls). That leaves almost nothing for top-ups. If the measured cost projects past $40, I stop and ask you, because the script would otherwise drop the last tickets. I assumed four defaults to check against r03-workflow.js. The runner is `python triage/run.py --config {config} --ticket {ticket} --seed {seed} --json`, and it prints label, reply, and metrics with cost_usd. grade.py takes `--answers`, `--in`, and `--out`. Runner transcripts are under `args.transcriptDir`. When the gates pass, I commit the script as `SPE r04 evaluate (harness)` and then launch it.

```js
export const meta = {
  name: 'spe-triage-eval',
  description: 'SPE eval for the triage agent. Runs trials per config and ticket, grades labels with code, judges reply tone with Opus, tops up split cells, and ends with failure analysis and a completeness critic.',
  phases: [
    { title: 'Trials' },
    { title: 'Scan' },
    { title: 'Grade' },
    { title: 'Judge' },
    { title: 'Top-up' },
    { title: 'Synthesis' },
  ],
};

// One round constant. Prompt text uses R and never a typed round number.
const ROUND = args.round ?? 4;
const R = `r${String(ROUND).padStart(2, '0')}`;

const CONFIGS = args.configs ?? ['B', 'C2'];
const TRIALS = args.trials ?? 5;
const TICKETS = args.tickets ?? [];                  // ticket IDs only, passed at launch
const EXPECT_TICKETS = args.expectTickets ?? 50;
const ONLY = args.only ?? null;                      // dry run, e.g. ['B:T001', 'C2:T001']
const DRY = Boolean(ONLY);
const CAP_USD = args.capUsd ?? 40;
const MAX_AGENTS = args.maxAgents ?? 130;
const BATCH = args.batchTickets ?? 5;
const TOPUP_PER_CELL = args.topupPerCell ?? 3;
const TOPUP_MAX_CELLS = args.topupMaxCells ?? 10;
// Estimates only. The runner reports measured cost_usd, which replaces trialUsd once 5 trials exist.
const EST = { trialUsd: 0.05, harnessAgentUsd: 0.12, judgeCallUsd: 0.15, ...(args.est ?? {}) };
const RUNNER = args.runnerCmd ?? 'python triage/run.py --config {config} --ticket {ticket} --seed {seed} --json';
const TRANSCRIPTS = args.transcriptDir ?? null;
const GRADER = 'spe/evals/graders/grade.py';
const ANSWERS = 'spe/evals/tasks/answers.json';
const RUBRIC = 'spe/evals/graders/judge.md';
const FORBIDDEN = /(^|\/)spe\/(evals|predictions)(\/|$)/;

// ---------- helpers ----------
let spent = 0;
let agentsUsed = 0;
const skipped = [];
const records = [];

const sum = a => a.reduce((x, y) => x + (y ?? 0), 0);
const mean = a => (a.length ? sum(a) / a.length : null);
const median = a => {
  if (!a.length) return null;
  const s = [...a].sort((x, y) => x - y);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};
const seeds = (from, n) => Array.from({ length: n }, (_, k) => from + k);
const trialCost = () => {
  const m = records.filter(r => r.cost_usd != null).map(r => r.cost_usd);
  return m.length >= 5 ? mean(m) : EST.trialUsd;
};
const fits = (usd, agents, reserve = 0) =>
  spent + usd + reserve <= CAP_USD && agentsUsed + agents <= MAX_AGENTS;
const cmd = (config, ticket, seed) =>
  RUNNER.replace('{config}', config).replace('{ticket}', ticket).replace('{seed}', String(seed));

function shuffle(arr, key) {
  // Deterministic order, so a rerun shows the judge the same order.
  let h = 0;
  for (const ch of key) h = (Math.imul(h, 31) + ch.charCodeAt(0)) >>> 0;
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    h = (Math.imul(h, 1103515245) + 12345) >>> 0;
    const j = h % (i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ---------- schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['runs', 'paths_read'],
  properties: {
    runs: {
      type: 'array',
      items: {
        type: 'object',
        required: ['config', 'seed', 'ok'],
        properties: {
          config: { type: 'string' },
          seed: { type: 'integer' },
          ok: { type: 'boolean' },
          harness_error: { type: 'string' },
          category: { type: 'string' },
          priority: { type: 'string' },
          reply: { type: 'string' },
          runtime_s: { type: 'number' },
          tool_calls: { type: 'integer' },
          tool_errors: { type: 'integer' },
          input_tokens: { type: 'integer' },
          output_tokens: { type: 'integer' },
          cost_usd: { type: 'number' },
        },
      },
    },
    paths_read: { type: 'array', items: { type: 'string' } },
  },
};

const SCAN_SCHEMA = {
  type: 'object',
  required: ['checked', 'peeked'],
  properties: {
    checked: { type: 'array', items: { type: 'string' } },
    peeked: {
      type: 'array',
      items: {
        type: 'object',
        required: ['label', 'evidence'],
        properties: { label: { type: 'string' }, evidence: { type: 'string' } },
      },
    },
  },
};

const GRADE_SCHEMA = {
  type: 'object',
  required: ['grades'],
  properties: {
    grades: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'category_ok', 'priority_ok'],
        properties: {
          id: { type: 'string' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
          expected_category: { type: 'string' },
          expected_priority: { type: 'string' },
        },
      },
    },
    grader_error: { type: 'string' },
  },
};

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['reply_id', 'score', 'pass', 'reason'],
        properties: {
          reply_id: { type: 'string' },
          score: { type: 'integer', minimum: 1, maximum: 5 },
          pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
      },
    },
  },
};

const FA_SCHEMA = {
  type: 'object',
  required: ['failure_types'],
  properties: {
    failure_types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'count', 'example_ids', 'how_to_spot', 'proposed_fix'],
        properties: {
          name: { type: 'string' },
          kind: { type: 'string', enum: ['agent', 'grader', 'harness', 'task'] },
          existing_f: { type: ['string', 'null'] },
          configs: { type: 'array', items: { type: 'string' } },
          count: { type: 'integer' },
          example_ids: { type: 'array', items: { type: 'string' } },
          how_to_spot: { type: 'string' },
          proposed_fix: { type: 'string' },
        },
      },
    },
    notes: { type: 'string' },
  },
};

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps', 'halt'],
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'string' } },
    halt: { type: 'array', items: { type: 'string' } },
  },
};

// ---------- units ----------
// A unit is one ticket with every config. A budget cut drops whole tickets, so configs stay paired.
let units;
if (ONLY) {
  const byTicket = {};
  for (const s of ONLY) {
    const [config, ticket] = s.split(':');
    (byTicket[ticket] ??= []).push(config);
  }
  units = Object.entries(byTicket).map(([ticket, configs]) => ({ ticket, configs }));
} else {
  if (TICKETS.length !== EXPECT_TICKETS) {
    throw new Error(`Got ${TICKETS.length} ticket IDs. The plan expects ${EXPECT_TICKETS}. Halt and ask the user.`);
  }
  units = TICKETS.map(ticket => ({ ticket, configs: CONFIGS }));
}
const trialsPerCell = DRY ? Math.min(TRIALS, args.dryTrials ?? 2) : TRIALS;
log(`${R}: ${units.length} tickets, configs ${CONFIGS.join(', ')}, ${trialsPerCell} trials per cell, cap $${CAP_USD}.${DRY ? ' Dry run.' : ''}`);

// ---------- trial runner ----------
function trialPrompt(ticket, jobs) {
  return [
    `You run eval trials for the triage agent in round ${R}. You are a runner. You do not triage tickets yourself.`,
    `Run each command below exactly once, in order, from the repository root:`,
    ...jobs.map(j => `- [config ${j.config}, seed ${j.seed}] ${cmd(j.config, ticket, j.seed)}`),
    `Each command prints one JSON object. For each one, copy label.category, label.priority, reply, and metrics (runtime_s, tool_calls, tool_errors, input_tokens, output_tokens, cost_usd) into a run entry with its config and seed. Copy the values unchanged. Do not correct, rewrite, or rerun a result.`,
    `If a command crashes, times out, or hits a rate limit, retry it once. If it fails again, set ok to false and put the error text in harness_error.`,
    `You may run only the commands above. Do not open, list, grep, or search any file. Never touch spe/evals/ or spe/predictions/.`,
    `In paths_read, list every file path you read or listed. The expected list is empty.`,
  ].join('\n');
}

async function runUnit(ticket, jobs, tag, phaseName) {
  const label = `${R}:${tag}:${ticket}`;
  const reserve = jobs.length * trialCost() + EST.harnessAgentUsd;
  spent += reserve;            // reserve before the await so parallel thunks see it
  agentsUsed += 1;
  const out = await agent(trialPrompt(ticket, jobs), { label, phase: phaseName, schema: TRIAL_SCHEMA, model: 'opus' });
  spent -= reserve;
  spent += EST.harnessAgentUsd;
  const selfPeek = (out?.paths_read ?? []).filter(p => FORBIDDEN.test(p));
  for (const j of jobs) {
    const r = out?.runs?.find(x => x.config === j.config && x.seed === j.seed);
    const rec = {
      id: `${j.config}:${ticket}:s${j.seed}`,
      config: j.config, ticket, seed: j.seed, tag, agentLabel: label,
      ok: Boolean(r?.ok),
      harness_error: r ? (r.harness_error ?? null) : 'runner agent returned no entry',
      category: r?.category ?? null,
      priority: r?.priority ?? null,
      reply: r?.reply ?? null,
      runtime_s: r?.runtime_s ?? null,
      tool_calls: r?.tool_calls ?? null,
      tool_errors: r?.tool_errors ?? null,
      tokens: r ? (r.input_tokens ?? 0) + (r.output_tokens ?? 0) : null,
      cost_usd: r?.cost_usd ?? null,
      voided: selfPeek.length ? `self-reported read: ${selfPeek.join(', ')}` : null,
      grade: null,
      tone: null,
    };
    spent += rec.cost_usd ?? EST.trialUsd;
    records.push(rec);
  }
}

// ---------- scan, grade ----------
async function scan(tag) {
  const labels = [...new Set(records.filter(r => r.tag === tag).map(r => r.agentLabel))];
  if (!labels.length) return { checked: [], missing: [], flagged: [] };
  if (!TRANSCRIPTS) {
    log(`Scan (${tag}): no transcriptDir given. Only self-reports were checked.`);
    return { checked: [], missing: labels, flagged: [] };
  }
  agentsUsed += 1;
  const out = await agent([
    `You audit eval runner transcripts for round ${R}. Do not run any eval command.`,
    `Transcript directory: ${TRANSCRIPTS}`,
    `For each runner label below, find its transcript. Flag the label if any tool call other than its listed triage command reads, lists, greps, or opens a path under spe/evals/ or spe/predictions/, or shows content from answers.json, grade.py, judge.md, or a predictions yaml.`,
    `Labels:`,
    ...labels.map(l => `- ${l}`),
    `Put every label you actually checked in checked. Put each flagged label in peeked with a short quote as evidence.`,
  ].join('\n'), { label: `${R}:scan:${tag}`, phase: 'Scan', schema: SCAN_SCHEMA, model: 'opus' });
  spent += EST.harnessAgentUsd;
  const flagged = new Map((out?.peeked ?? []).map(p => [p.label, p.evidence]));
  for (const r of records) {
    if (r.tag === tag && flagged.has(r.agentLabel)) r.voided = `transcript: ${flagged.get(r.agentLabel)}`;
  }
  const checked = new Set(out?.checked ?? []);
  const missing = labels.filter(l => !checked.has(l));
  if (missing.length) log(`Scan (${tag}): ${missing.length} transcripts not checked: ${missing.join(', ')}`);
  if (flagged.size) log(`Scan (${tag}): voided runners ${[...flagged.keys()].join(', ')}`);
  return { checked: [...checked], missing, flagged: [...flagged.keys()] };
}

async function grade(tag) {
  const rows = records
    .filter(r => r.tag === tag && r.ok && !r.voided)
    .map(r => ({ id: r.id, ticket: r.ticket, label: { category: r.category, priority: r.priority } }));
  if (!rows.length) return { graded: 0, missing: 0, grader_error: null };
  const inFile = `spe/evals/runs/${R}/labels-${tag}.jsonl`;
  const outFile = `spe/evals/runs/${R}/graded-${tag}.json`;
  agentsUsed += 1;
  const out = await agent([
    `You run the code grader for round ${R}. You do not grade by judgment.`,
    `1. Write these rows to ${inFile}, one JSON object per line, unchanged:`,
    JSON.stringify(rows),
    `2. Run: python ${GRADER} --answers ${ANSWERS} --in ${inFile} --out ${outFile}`,
    `3. Return the grader's per-row output as grades. Copy id, category_ok, priority_ok, expected_category, and expected_priority exactly as grade.py wrote them.`,
    `Do not edit the grader, the answers, or any row. If grade.py errors or skips rows, put its error text in grader_error.`,
  ].join('\n'), { label: `${R}:grade:${tag}`, phase: 'Grade', schema: GRADE_SCHEMA, model: 'opus' });
  spent += EST.harnessAgentUsd;
  if (out?.grader_error) log(`Grade (${tag}): grader error: ${out.grader_error}`);
  const byId = new Map((out?.grades ?? []).map(g => [g.id, g]));
  let missing = 0;
  for (const r of records) {
    if (r.tag === tag && r.ok && !r.voided) {
      const g = byId.get(r.id);
      if (g) r.grade = g;
      else missing += 1;
    }
  }
  if (missing) log(`Grade (${tag}): ${missing} completed trials have no grade. Treat this as a grader bug.`);
  return { graded: byId.size, missing, grader_error: out?.grader_error ?? null };
}

// ---------- Trials ----------
phase('Trials');
const JUDGE_RESERVE = units.length * EST.judgeCallUsd;
const ran = [];
for (let i = 0; i < units.length; i += BATCH) {
  const batch = units.slice(i, i + BATCH);
  const cost = sum(batch.map(u => u.configs.length * trialsPerCell * trialCost() + EST.harnessAgentUsd));
  if (!fits(cost, batch.length, JUDGE_RESERVE)) {
    for (const u of batch) {
      skipped.push({
        ticket: u.ticket, configs: u.configs, phase: 'Trials',
        reason: `cap: spent ${spent.toFixed(2)} + batch ${cost.toFixed(2)} + judge reserve ${JUDGE_RESERVE.toFixed(2)} > ${CAP_USD}`,
      });
    }
    log(`Skipped tickets ${batch.map(u => u.ticket).join(', ')}: spend or agent cap.`);
    continue;
  }
  await parallel(batch.map(u => () =>
    runUnit(u.ticket, u.configs.flatMap(config => seeds(1, trialsPerCell).map(seed => ({ config, seed }))), 'base', 'Trials')));
  ran.push(...batch);
  log(`Trials: ${ran.length}/${units.length} tickets done. Spent about $${spent.toFixed(2)}.`);
}

// ---------- Scan ----------
phase('Scan');
const baseScan = await scan('base');

// ---------- Grade ----------
phase('Grade');
const baseGrade = await grade('base');

// ---------- Judge ----------
phase('Judge');
const judgeTickets = [...new Set(records.filter(r => r.tag === 'base').map(r => r.ticket))];
await parallel(judgeTickets.map(ticket => async () => {
  const recs = records.filter(r => r.tag === 'base' && r.ticket === ticket && r.ok && !r.voided && r.reply);
  if (!recs.length) return;
  if (!fits(EST.judgeCallUsd, 1)) {
    skipped.push({ ticket, phase: 'Judge', reason: 'spend or agent cap' });
    log(`Judge skipped for ${ticket}: cap.`);
    return;
  }
  spent += EST.judgeCallUsd;
  agentsUsed += 1;
  const order = shuffle(recs, `${R}:${ticket}`);
  const ids = order.map((rec, k) => ({ reply_id: `reply-${k + 1}`, rec }));
  const out = await agent([
    `You judge the tone of first replies to a support ticket for round ${R}.`,
    `Read the rubric at ${RUBRIC} and apply it as written. Read the text of ticket ${ticket} from spe/evals/tasks/. Do not open answers.json or anything under spe/predictions/.`,
    `The replies below come from different agent setups in a random order. You are not told which setup wrote which reply. Score each reply on its own against the rubric. Do not rank replies against each other.`,
    `For each reply, give a score from 1 to 5, set pass to true when the rubric's pass line is met, and give a one-sentence reason.`,
    ...ids.map(x => `${x.reply_id}:\n<<<\n${x.rec.reply}\n>>>`),
  ].join('\n\n'), { label: `${R}:judge:${ticket}`, phase: 'Judge', schema: JUDGE_SCHEMA, model: 'opus' });
  const byId = new Map((out?.scores ?? []).map(s => [s.reply_id, s]));
  for (const x of ids) {
    const s = byId.get(x.reply_id);
    if (s) x.rec.tone = { score: s.score, pass: s.pass, reason: s.reason };
  }
}));
log('Judge: Opus scores tone for Sonnet trials. Both models are Claude. No judge from another model family was available.');

// ---------- Top-up ----------
phase('Top-up');
const halts = [];
if (skipped.some(s => s.phase === 'Trials')) halts.push('Spend or agent cap hit during Trials. Some tickets did not run.');
if (baseGrade.missing || baseGrade.grader_error) halts.push('Grader problem during base grading.');
if (records.some(r => r.voided)) halts.push('A runner read a forbidden path. Check for a leaked answer key.');

const splitCells = [];
let topupScan = null;
let topupGrade = null;
if (halts.length) {
  log(`Top-up skipped because of halts: ${halts.join(' ')}`);
} else {
  for (const u of ran) {
    for (const config of u.configs) {
      const g = records.filter(r => r.tag === 'base' && r.config === config && r.ticket === u.ticket && r.grade);
      const pass = g.filter(r => r.grade.category_ok && r.grade.priority_ok).length;
      if (pass > 0 && pass < g.length) splitCells.push({ config, ticket: u.ticket, pass, of: g.length });
    }
  }
  const chosen = splitCells.slice(0, TOPUP_MAX_CELLS);
  if (splitCells.length > chosen.length) {
    log(`Top-up: ${splitCells.length} split cells, cap ${TOPUP_MAX_CELLS}. Not topped up: ${splitCells.slice(TOPUP_MAX_CELLS).map(c => `${c.config}:${c.ticket}`).join(', ')}`);
  }
  const byTicket = {};
  for (const c of chosen) (byTicket[c.ticket] ??= []).push(c.config);
  await parallel(Object.entries(byTicket).map(([ticket, configs]) => async () => {
    const cost = configs.length * TOPUP_PER_CELL * trialCost() + EST.harnessAgentUsd;
    if (!fits(cost, 1)) {
      skipped.push({ ticket, configs, phase: 'Top-up', reason: 'spend or agent cap' });
      log(`Top-up skipped for ${ticket} (${configs.join(', ')}): cap.`);
      return;
    }
    await runUnit(ticket, configs.flatMap(config => seeds(TRIALS + 1, TOPUP_PER_CELL).map(seed => ({ config, seed }))), 'topup', 'Top-up');
  }));
  if (records.some(r => r.tag === 'topup')) {
    topupScan = await scan('topup');
    topupGrade = await grade('topup');
    log('Top-up trials are code-graded only. Tone stays measured on the base trials.');
  }
}

// ---------- Synthesis ----------
phase('Synthesis');
function summarize(recs) {
  const done = recs.filter(r => r.ok && !r.voided);
  const graded = done.filter(r => r.grade);
  const toned = done.filter(r => r.tone);
  const calls = sum(done.map(r => r.tool_calls));
  return {
    trials: recs.length,
    completed: done.length,
    harness_errors: recs.filter(r => !r.ok).length,
    voided: recs.filter(r => r.voided).length,
    graded: graded.length,
    category_acc: mean(graded.map(r => (r.grade.category_ok ? 1 : 0))),
    priority_acc: mean(graded.map(r => (r.grade.priority_ok ? 1 : 0))),
    both_acc: mean(graded.map(r => (r.grade.category_ok && r.grade.priority_ok ? 1 : 0))),
    tone_judged: toned.length,
    tone_mean: mean(toned.map(r => r.tone.score)),
    tone_pass: mean(toned.map(r => (r.tone.pass ? 1 : 0))),
    runtime_median_s: median(done.map(r => r.runtime_s).filter(x => x != null)),
    tool_calls_mean: mean(done.map(r => r.tool_calls).filter(x => x != null)),
    tool_error_rate: calls ? sum(done.map(r => r.tool_errors)) / calls : null,
    tokens_mean: mean(done.map(r => r.tokens).filter(x => x != null)),
    cost_usd: sum(done.map(r => r.cost_usd)),
  };
}
const summary = {};
for (const c of CONFIGS) {
  summary[c] = {
    base: summarize(records.filter(r => r.config === c && r.tag === 'base')),
    with_topup: summarize(records.filter(r => r.config === c)),
  };
}

const failing = records
  .filter(r => !r.ok || r.voided || (r.grade && !(r.grade.category_ok && r.grade.priority_ok)) || (r.tone && !r.tone.pass))
  .map(r => ({
    id: r.id, config: r.config, ticket: r.ticket, tag: r.tag,
    ok: r.ok, harness_error: r.harness_error, voided: r.voided,
    got: { category: r.category, priority: r.priority },
    expected: r.grade ? { category: r.grade.expected_category, priority: r.grade.expected_priority } : null,
    tone: r.tone,
    reply_excerpt: r.reply ? r.reply.slice(0, 400) : null,
  }));

agentsUsed += 1;
const failures = await agent([
  `You do failure analysis for round ${R} of the triage agent eval. Configs: ${CONFIGS.join(', ')}.`,
  `Per-config summary:`,
  JSON.stringify(summary),
  `Failing, voided, and errored trials:`,
  JSON.stringify(failing),
  `Group these into failure types. Read spe/failures.md and reuse an existing F-number in existing_f when a type matches. Set existing_f to null for a new type.`,
  `Use kind "grader" when the grade looks wrong rather than the agent. Use "harness" for runner errors. Count only completed trials as agent failures.`,
  `Do not edit any file. Do not read spe/predictions/. The close-out step compares results to predictions.`,
].join('\n'), { label: `${R}:failure-analysis`, phase: 'Synthesis', schema: FA_SCHEMA, model: 'opus' });
spent += EST.harnessAgentUsd;

const coverage = {
  dry_run: DRY,
  tickets_planned: units.length,
  tickets_run: ran.length,
  expected_base_trials: ran.reduce((n, u) => n + u.configs.length * trialsPerCell, 0),
  base_trials_recorded: records.filter(r => r.tag === 'base').length,
  ungraded_base: baseGrade.missing,
  grader_error: baseGrade.grader_error,
  unjudged_base: records.filter(r => r.tag === 'base' && r.ok && !r.voided && r.reply && !r.tone).length,
  scan_missing: [...(baseScan.missing ?? []), ...(topupScan?.missing ?? [])],
  voided: records.filter(r => r.voided).map(r => r.id),
  skipped,
  split_cells: splitCells.length,
  topup_grade: topupGrade,
  spend_usd: +spent.toFixed(2),
  cap_usd: CAP_USD,
  agents_used: agentsUsed,
  halts,
};

agentsUsed += 1;
const critic = await agent([
  `You are the completeness critic for round ${R}. Do not edit any file.`,
  `Coverage:`,
  JSON.stringify(coverage),
  `Per-config summary:`,
  JSON.stringify(summary),
  `List every gap that could make the per-config numbers misleading. Check for unequal tickets across configs, voids, harness errors, skips, missing grades or judge scores, unchecked transcripts, and grader errors.`,
  `In halt, list anything that must stop the loop: a budget cap hit, a leaked answer key, a broken grader, or a decision only the user can make. Set complete to true only if no gap remains.`,
].join('\n'), { label: `${R}:critic`, phase: 'Synthesis', schema: CRITIC_SCHEMA, model: 'opus' });
spent += EST.harnessAgentUsd;

log(`${R} done. Spend about $${spent.toFixed(2)} of $${CAP_USD}. Agents ${agentsUsed}/${MAX_AGENTS}. Halts: ${[...halts, ...(critic?.halt ?? [])].join(' ') || 'none'}.`);

return {
  round: R,
  dry_run: DRY,
  configs: CONFIGS,
  trials_per_cell: trialsPerCell,
  summary,
  coverage,
  failures,
  critic,
  spend_note: 'Runner cost is measured from cost_usd. Harness, judge, and analysis agent cost is estimated.',
  judge_note: 'Opus judges Sonnet replies. Both are Claude models. No judge from another model family was available.',
  records: records.map(({ reply, ...rest }) => rest),
};
